import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`wag-profile-audit`,heroTitle:`Optimize your Wag profile in minutes`,heroSubtitle:`Perplexity Computer audits your profile, benchmarks top sitters in your area, and delivers a rewritten listing with pricing strategy — automatically.`,inputUrlCta:`Audit my profile`,inputUrlPlaceholder:`your Wag profile URL`,inputUrlPrefill:`Go to {url} and perform a complete Wag profile audit. 1) Extract and evaluate the current bio, service descriptions, photos, pricing, calendar availability, and review responses. 2) Identify the sitter's zip code and find the top 5 highest-ranked sitters in that area — analyze their bios, pricing, services offered, review counts, response patterns, and photo quality. 3) Score the original profile against these top competitors across each category: bio quality, photo appeal, pricing competitiveness, calendar completeness, and review engagement. 4) Rewrite the full profile — bio, service descriptions, and photo captions — using language and keywords that match what top-ranked sitters use. 5) Build a competitive pricing strategy based on local market rates, showing recommended prices per service type with justification. 6) Create a review-request message template the sitter can send to past clients to boost review volume. 7) Deliver everything in a single report with before/after scores, the rewritten profile copy, pricing recommendations, and the review-request template.`,heroOverlaySteps:[`Extracting your bio, services, photos, pricing, and reviews`,`Finding and analyzing the top 5 sitters in your zip code`,`Benchmarking your profile against local competition`,`Rewritten profile, pricing strategy, and review template — ready to use`],generatingSteps:[`Visiting {url} to extract your profile details, pricing, and review history`,`Designing an agent to research and benchmark the top sitters in your zip code`,`Configuring profile rewriting, pricing analysis, and review-request generation`,`Setting up your deliverable report with before/after scores and ready-to-paste copy`],featureSectionTitle:`From profile URL to top-ranked listing`,featureCardTitles:[`Connects to your everyday tools`,`Outputs you can paste today`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Sheets, Notion, Canva — Computer plugs into your tools so your rewritten profile and pricing strategy are ready to edit and share.`,`Rewritten bio and service descriptions. Competitive pricing breakdown by service type. Before/after profile scores. A review-request template to send to past clients.`],capabilitySectionTitle:`Your profile coach, on autopilot`,capabilitySectionSubtitle:`Paste your Wag URL, step away, come back to a fully optimized listing.`,capabilityCards:[{title:`Profile Audit`,description:`Computer can evaluate your bio, photos, service descriptions, pricing, calendar availability, and review responses — scoring each against platform best practices.`},{title:`Competitor Benchmarking`,description:`Computer can find the top 5 sitters in your zip code and analyze exactly what makes their profiles rank higher — language, pricing, review volume, and photo quality.`},{title:`Profile Rewriting`,description:`Computer can rewrite your entire profile — bio, service descriptions, and photo captions — using keywords and patterns from the highest-ranked local sitters.`},{title:`Connect Your Tools`,description:`Computer can export your rewritten profile and pricing strategy to Google Docs, Google Sheets, and Notion — so everything lives where you already work.`},{title:`Remember & Improve`,description:`Computer can remember your services, zip code, pricing history, and past audits — so every future optimization builds on your progress.`},{title:`Monitor & Alert`,description:`Computer can re-check competitor pricing and rankings monthly and alert you when local market rates shift or new top sitters emerge.`}]});export{t as default};
